package com.ethk3.novaonepro.strategyv2;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class RepairSetIntersectionR30Test {
 static ReplayDatasetR27 data(boolean compatible){List<ReplayDatasetR27.Row> rows=new ArrayList<>();for(int t=0;t<200;t++){int[] d=new int[10];for(int p=0;p<10;p++)d[p]=p+1;if(compatible){d[0]=1+t%3;d[1]=1+(t+1)%3;d[9]=1+(t+2)%3;for(int p=2;p<9;p++)d[p]=p+2;}String issue=String.format(java.util.Locale.ROOT,"20261030%04d",t+1);rows.add(new ReplayDatasetR27.Row(issue,com.ethk3.novaonepro.TargetIssueResolver.sequenceOrdinalSU1(issue),d));}return ReplayDatasetR27.of(rows);}
 static PolicySpecR27 policy(){return SetIntersectionPolicyR30.spec(1,8,32,IdeaFamilyR27.meta("I14","TEST",0,1,"HOST_SYNTHETIC_EXACT_SET"));}
 @Test public void supportedK3CannotEscapeOriginalIntersection(){ReplayDatasetR27 d=data(true);FeatureCacheR27 f=new FeatureCacheR27(d);PolicySpecR27 p=policy();Map<String,Object> e=SetIntersectionPolicyR30.support(f,100,1,8,32);assertEquals("SUPPORTED_K3",e.get("status"));int mask=((Number)e.get("intersectionMask")).intValue();assertEquals(7,mask);double[] out=ReplayEvaluatorR27.predictNext(p,f,1);int got=(1<<(int)out[10])|(1<<(int)out[11])|(1<<(int)out[12]);assertEquals(mask,got);for(int k=0;k<10;k++)assertEquals((mask&(1<<k))!=0?1.0/3:0,out[k],0);assertEquals(0,e.get("filledNumbers"));assertEquals(p.policyHash(),PolicySpecR27.parse(p.fullJson()).policyHash());assertTrue(PolicyContractR30.violations(p).isEmpty());}
 @Test public void tooSmallIntersectionExplicitlyAbstainsWithoutFilling(){ReplayDatasetR27 d=data(false);FeatureCacheR27 f=new FeatureCacheR27(d);Map<String,Object> e=SetIntersectionPolicyR30.support(f,100,1,8,32);assertEquals("ABSTAIN_INTERSECTION_LT3",e.get("status"));assertEquals(2,e.get("intersectionCandidates"));assertEquals(0,e.get("filledNumbers"));double[] out=ReplayEvaluatorR27.predictNext(policy(),f,1);for(double v:out)assertTrue(Double.isNaN(v));}
 @Test public void futureLabelsDoNotChangePastSupportAndUpdaterCannotChangeTheSet(){ReplayDatasetR27 d=data(true);FeatureCacheR27 a=new FeatureCacheR27(d);int[][] draws=d.draws.clone();for(int t=100;t<draws.length;t++)draws[t]=d.draws[0].clone();FeatureCacheR27 b=new FeatureCacheR27(d.withDraws(draws));double[] x=a.leaf("set_intersection",1,8,32),y=b.leaf("set_intersection",1,8,32);for(int i=0;i<1010;i++)assertEquals(Double.doubleToLongBits(x[i]),Double.doubleToLongBits(y[i]));assertFalse(PolicyContractR30.violations(policy().withUpdater(.1,0,policy().meta)).isEmpty());assertFalse(PolicyContractR30.violations(policy().withAst(PolicyAstR27.op("zscore",policy().ast),policy().meta)).isEmpty());}
 @Test public void completeInputAbstentionIsLawfulButGapsStillFailTheOriginalAvailabilityGate(){ReplayDatasetR27 d=data(false);BirthGateR27.Verdict lawful=new BirthGateR27(new FeatureCacheR27(d),d.size()).checkCandidate(policy());assertTrue(lawful.detail,lawful.ok);assertEquals(0,lawful.signature.length);List<ReplayDatasetR27.Row> rows=new ArrayList<>();for(int i=0;i<d.size();i++){String issue=String.format(java.util.Locale.ROOT,"20261030%04d",i*4+1);rows.add(new ReplayDatasetR27.Row(issue,com.ethk3.novaonepro.TargetIssueResolver.sequenceOrdinalSU1(issue),d.draws[i]));}ReplayDatasetR27 gaps=ReplayDatasetR27.of(rows);BirthGateR27.Verdict missing=new BirthGateR27(new FeatureCacheR27(gaps),gaps.size()).checkCandidate(policy());assertFalse(missing.ok);assertTrue(missing.detail.startsWith("AVAILABLE_ROWS="));}
}
